// The tool catalogue. One entry per operation the add-in implements, in one place, because three
// things read it and they must not drift apart: the MCP server (registration and schemas), the tests
// (catalogue invariants), and the README's tool table (generated by `npm run tools:table`).
//
// `write: true` means the tool changes the model. Those are refused unless the operator turned
// writes on for BOTH processes (server --allow-writes and the add-in), and every one of them takes
// `apply: false` by default so the first answer is a preview, not a change. See docs/security.md.
//
// `op` is the bridge operation (docs/protocol.md). The server never talks Revit API directly: it
// forwards { op, args } to the add-in, which does the Revit work on Revit's own thread.
import { z } from 'zod';

const elementId = z.number().int().positive().describe('Revit element id, as returned by query_elements');
const limit = z.number().int().min(1).max(500).optional().describe('Maximum rows to return (default 50, max 500)');

export const TOOLS = [
  {
    name: 'revit_status',
    title: 'Revit status',
    op: 'status',
    write: false,
    description:
      'Is Revit open, which document is active, its units and worksharing state, and whether the add-in will accept writes. '
      + 'Call this first when anything else fails: it tells you whether the bridge is up at all.',
    params: {},
  },
  {
    name: 'model_overview',
    title: 'Model overview',
    op: 'model.overview',
    write: false,
    description:
      'The model at a glance: file name, Revit version, level, sheet and view counts, the biggest categories by element count, '
      + 'and how many warnings Revit is holding. Start here for "what is in this model".',
    params: {
      category_limit: z.number().int().min(1).max(100).optional().describe('How many categories to list by size (default 20)'),
    },
  },
  {
    name: 'list_levels',
    title: 'List levels',
    op: 'levels.list',
    write: false,
    description: 'Every level with its elevation and how many elements sit on it, so you can see what the model is organised around.',
    params: {},
  },
  {
    name: 'list_categories',
    title: 'List categories',
    op: 'categories.list',
    write: false,
    description: 'Model categories with instance counts — walls, doors, windows, rooms, furniture and anything else the model uses.',
    params: { limit },
  },
  {
    name: 'query_elements',
    title: 'Query elements',
    op: 'elements.query',
    write: false,
    description:
      'Find elements by category, level, family, type or a parameter value. Returns a compact row per element (id, category, family/type, '
      + 'level, mark) — the ids are what element_details, set_parameter and the other element tools take.',
    params: {
      category: z.string().describe('Category name, e.g. "Walls", "Doors", "Rooms"'),
      level: z.string().optional().describe('Level name, e.g. "L2"'),
      family: z.string().optional().describe('Family name, e.g. "Single-Flush"'),
      type: z.string().optional().describe('Type name, e.g. "0915 x 2134mm"'),
      parameter: z.string().optional().describe('Parameter name to match on, e.g. "Fire Rating"'),
      value: z.string().optional().describe('Value for `parameter` (exact, case-insensitive substring)'),
      limit,
      offset: z.number().int().min(0).optional().describe('Rows to skip, for paging (default 0)'),
    },
  },
  {
    name: 'element_details',
    title: 'Element details',
    op: 'element.details',
    write: false,
    description:
      'One element in full: instance and type parameters, family/type, level, host, workset and bounding box. '
      + 'Use it before set_parameter to see what a parameter is called and what it holds now.',
    params: { element_id: elementId },
  },
  {
    name: 'list_views',
    title: 'List views',
    op: 'views.list',
    write: false,
    description: 'Views in the model (floor plans, sections, 3D, schedules) with their type, level and sheet, if placed.',
    params: {
      type: z.string().optional().describe('Filter by view type, e.g. "FloorPlan", "Section", "ThreeD"'),
      limit,
    },
  },
  {
    name: 'list_sheets',
    title: 'List sheets',
    op: 'sheets.list',
    write: false,
    description: 'Sheets with number, name and the views placed on them — the drawing set as issued.',
    params: { limit },
  },
  {
    name: 'list_families',
    title: 'List families',
    op: 'families.list',
    write: false,
    description: 'Loaded families with how many types each carries and how many instances are placed.',
    params: { limit },
  },
  {
    name: 'model_warnings',
    title: 'Model warnings',
    op: 'warnings.list',
    write: false,
    description:
      'Revit\'s own warnings (rooms not enclosed, duplicate instances, overlapping walls) with the elements they point at. '
      + 'A warning is a prompt to look, not a defect finding.',
    params: { limit },
  },
  {
    name: 'list_schedules',
    title: 'List schedules',
    op: 'schedules.list',
    write: false,
    description: 'Schedule views in the model — quantities, door schedules, room schedules, sheets of data.',
    params: {},
  },
  {
    name: 'read_schedule',
    title: 'Read schedule',
    op: 'schedule.read',
    write: false,
    description:
      'The rows and columns of one schedule as it computes them, for quantities and take-off questions. '
      + 'Header names are Revit\'s; totals rows are marked as such.',
    params: {
      schedule: z.string().describe('Schedule name as list_schedules reports it'),
      limit,
    },
  },
  {
    name: 'current_selection',
    title: 'Current selection',
    op: 'selection.get',
    write: false,
    description:
      'What the user has selected in Revit right now. The fastest way to answer "this wall" — ask, then work from these ids.',
    params: {},
  },
  {
    name: 'export_view_image',
    title: 'Export view image',
    op: 'view.export_image',
    write: false,
    description:
      'Render a view (the active one by default) to a PNG file and return its path and size, so a picture can be read alongside the data. '
      + 'Writes an image file in a temp folder; it never changes the model.',
    params: {
      view: z.string().optional().describe('View name; omit for the active view'),
      width: z.number().int().min(200).max(4000).optional().describe('Image width in pixels (default 1600)'),
    },
  },
  {
    name: 'set_parameter',
    title: 'Set parameter',
    op: 'parameter.set',
    write: true,
    description:
      'Change one parameter on one element. Preview by default (apply: false) and returns the old and new value; with apply: true it runs '
      + 'in a single Revit transaction, so one Ctrl+Z undoes it. Requires writes to be enabled on both the server and the add-in, and never '
      + 'touches type parameters that would change every instance.',
    params: {
      element_id: elementId,
      parameter: z.string().describe('Instance parameter name, e.g. "Mark", "Comments", "Fire Rating"'),
      value: z.string().describe('New value, as text (numbers and yes/no are parsed by Revit\'s own rules)'),
      apply: z.boolean().optional().describe('false (default) previews the change; true applies it in one transaction'),
    },
  },
];

/** The write tools, for the guard rails. */
export const WRITE_TOOLS = TOOLS.filter(t => t.write);

/** The zod shape MCP registration wants, from the catalogue. */
export function schemaFor(tool) {
  return tool.params;
}
